#pragma once
// A sparse bitmap font: only the glyphs a font needs, each looked up by its Unicode code point.
// The headers in this folder are generated by tools/fonts/make_font.py (build_fonts.sh): Adafruit GFX
// glyph records over one bitmap, plus a sorted table of code points (binary search, src/ui/GlyphText.h).
#include <cstdint>

#include <Adafruit_GFX.h>  // GFXglyph (on the PC: tests/host/shim)

struct SparseGFXfont {
  const uint8_t* bitmap;     // all glyph bitmaps, rows padded to whole bytes, MSB first
  const GFXglyph* glyph;     // one record per glyph, in the order of charMap
  const uint32_t* charMap;   // the code points, ascending
  uint16_t glyphCount;
  uint8_t yAdvance;          // the font's size in pixels (a missing glyph advances half of it)
};
